\section{TQFT state on an Euclidean tetrahedron:}


\subsection{A graphical representation of the Topological Quantum Field (TQFT) State on the Tetrahedron}
\begin{center}
\begin{pspicture}(-4,-1)(4,4)
\psline[linecolor=blue,linewidth=0.04]{->}(-1.5,0)(0,-1.5)
\psline[linecolor=blue,linewidth=0.04]{->}(0,-1.5)(3,0)
\psline[linecolor=blue,linewidth=0.04]{->}(3,0)(0.5,3)
\psline[linecolor=blue,linewidth=0.04]{->}(0.5,3)(-1.5,0)
\rput(-1.7,0){2}
\rput(0,-1.75){3}
\rput(3.2,0){4}
\rput(0.5,3.25){1}
\psline[linecolor=blue,linewidth=0.04](0,-1.5)(0.5,3)
\psline[linestyle=dashed](-1.5,0)(3,0)
\end{pspicture}
\end{center}

{\em Note: the $pstricks$ code for the graphics is as provided by pahio.}




\end{document}
